From 9848efd649e92cf00bfc8e188ff5c0e621924703 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:39:52 +0100
Subject: [PATCH] applet, kded: allow deleting vaults whose encrypted folder is
 missing

Such vaults were shown disabled, so Configure Vault and its Delete page
were unreachable, and kded refused to delete them anyway. Keep Configure
available for them and make deletion skip paths that no longer exist.

BUG: 425043
---
 kded/engine/fusebackend_p.cpp            | 16 ++++++++++++++--
 kded/engine/vault.cpp                    |  3 +++
 plasma/package/contents/ui/VaultItem.qml |  3 ++-
 3 files changed, 19 insertions(+), 3 deletions(-)

diff --git a/kded/engine/fusebackend_p.cpp b/kded/engine/fusebackend_p.cpp
index 603ba7c..f0a50c4 100644
--- a/kded/engine/fusebackend_p.cpp
+++ b/kded/engine/fusebackend_p.cpp
@@ -7,6 +7,7 @@
 #include "fusebackend_p.h"

 #include <QDir>
+#include <QFileInfo>
 #include <QRegularExpression>
 #include <QStandardPaths>
 #include <QUrl>
@@ -176,8 +177,19 @@ FutureResult<> FuseBackend::dismantle(const Device &device, const MountPoint &mo

     lockMountPoint(mountPoint, false);

-    // Removing the data and the mount point
-    return transform(makeFuture<KJob *>(KIO::del({QUrl::fromLocalFile(device.data()), QUrl::fromLocalFile(mountPoint.data())})), [](KJob *job) {
+    // Removing the data and the mount point, if they still exist
+    QList<QUrl> urls;
+    for (const auto &path : {device.data(), mountPoint.data()}) {
+        if (QFileInfo::exists(path)) {
+            urls << QUrl::fromLocalFile(path);
+        }
+    }
+
+    if (urls.isEmpty()) {
+        return makeReadyFuture(Result<>::success());
+    }
+
+    return transform(makeFuture<KJob *>(KIO::del(urls)), [](KJob *job) {
         job->deleteLater();
         return job->error() == 0 ? Result<>::success() : Result<>::error(Error::DeletionError, job->errorString());
     });
diff --git a/kded/engine/vault.cpp b/kded/engine/vault.cpp
index f488d00..2796ab6 100644
--- a/kded/engine/vault.cpp
+++ b/kded/engine/vault.cpp
@@ -565,6 +565,9 @@ FutureResult<> Vault::dismantle(const Payload &payload)
 {
     const auto resolvedPath = [] (const QString& path) {
         auto result = QDir(path).canonicalPath();
+        if (result.isEmpty()) {
+            result = QDir::cleanPath(path);
+        }
         if (!result.endsWith(QLatin1Char('/'))) {
             result += QLatin1Char('/');
         }
diff --git a/plasma/package/contents/ui/VaultItem.qml b/plasma/package/contents/ui/VaultItem.qml
index a67ff86..b236ad9 100644
--- a/plasma/package/contents/ui/VaultItem.qml
+++ b/plasma/package/contents/ui/VaultItem.qml
@@ -38,6 +38,7 @@ PlasmaExtras.ExpandableListItem {
     subtitle: model.message
     subtitleCanWrap: true
     defaultActionButtonAction: QQC2.Action {
+        enabled: root.model.isEnabled
         icon.name: root.model.isOpened ? "lock-symbolic" : "unlock-symbolic"
         text: root.model.isOpened ? i18nd("plasmavault-kde", "Lock Vault") : i18nd("plasmavault-kde", "Unlock and Open")
         onTriggered: source => {
@@ -49,7 +50,6 @@ PlasmaExtras.ExpandableListItem {
         }
     }
     isBusy: Plasmoid.busy
-    enabled: model.isEnabled
     contextualActions: [
         QQC2.Action {
             enabled: root.model.isOpened
@@ -60,6 +60,7 @@ PlasmaExtras.ExpandableListItem {
             }
         },
         QQC2.Action {
+            enabled: root.model.isEnabled
             icon.name: root.model.isOpened ? "window-close-symbolic" : "unlock-symbolic"
             text: root.model.isOpened ? i18nd("plasmavault-kde", "Forcefully Lock Vault") : i18nd("plasmavault-kde", "Unlock Vault")
             onTriggered: source => {
